// Anomaly Detection Post-Process
const input = $input.first().json;
const rawResponse = typeof input.text === 'string' ? input.text : (input.response || input.output || JSON.stringify(input));

let anomalyResult;
try {
  const cleaned = rawResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  anomalyResult = JSON.parse(cleaned);
} catch(e) {
  anomalyResult = {
    anomaly_assessment: 'NORMAL',
    reasoning: 'Unable to parse anomaly LLM response, defaulting to NORMAL',
    recommended_action: 'PROCEED',
    confidence: 0.5
  };
}

const prev = $('Compute Anomaly Scores1').first().json;

// Merge anomaly LLM assessment back into the flow
return [{
  json: {
    ...prev,
    anomaly_llm: anomalyResult,
    agent_assessments: {
      ...(prev.agent_assessments || {}),
      anomaly_agent: {
        agent: 'AnomalyDetectionAgent',
        assessment: anomalyResult.anomaly_assessment,
        action: anomalyResult.recommended_action,
        confidence: anomalyResult.confidence,
        z_score: prev.anomaly.z_score,
        composite_score: prev.anomaly.composite_score
      }
    }
  }
}];

// === SWARM AGENT 2: Currency Risk — Live FX + CIP Formula ===
const prev = $('Anomaly Post-Process1').first().json;
const currency = prev.execution_payload.currency;
const amount = prev.execution_payload.amount;
const dueDate = prev.invoice_data.due_date;

if (currency === 'INR') {
  return [{
    json: {
      ...prev,
      currency_risk: {
        analysis: 'DOMESTIC', risk_level: 'NONE', market_type: 'DOMESTIC',
        proceed: true, inr_amount: amount, exposure: 0,
        hedging: { recommended: false, reason: 'Domestic currency' },
        swarm_vote: 'GO', swarm_confidence: 0.95,
        rate_source: 'N/A'
      }
    }
  }];
}

// === LIVE FX RATES with static fallback ===
const fxData = prev.live_fx || null;
let liveRates = {};
let rateSource = 'STATIC_FALLBACK';

try {
  if (fxData && fxData.result === 'success' && fxData.rates) {
    const r = fxData.rates;
    for (const c of ['USD','EUR','GBP','AED','SGD','JPY']) {
      if (r[c]) liveRates[c] = parseFloat((1 / r[c]).toFixed(4));
    }
    rateSource = 'LIVE_API (open.er-api.com)';
  }
} catch(e) { /* fall through to static */ }

const staticRates = {USD:83.50, EUR:91.20, GBP:106.30, AED:22.70, SGD:62.10, JPY:0.56};
const spotRate = liveRates[currency] || staticRates[currency] || 83.50;

// === COVERED INTEREST PARITY: F = S x (1 + r_dom x T) / (1 + r_for x T) ===
const interestRates = {INR:0.065, USD:0.0525, EUR:0.0375, GBP:0.0425, AED:0.054, SGD:0.035, JPY:0.001};
const r_dom = interestRates.INR;
const r_for = interestRates[currency] || 0.04;

let T = 30 / 365;
if (dueDate) {
  const diffMs = new Date(dueDate) - new Date();
  const diffDays = Math.max(1, diffMs / 86400000);
  T = diffDays / 365;
}

const forward30d = spotRate * (1 + r_dom * (30/365)) / (1 + r_for * (30/365));
const forward90d = spotRate * (1 + r_dom * (90/365)) / (1 + r_for * (90/365));
const forwardDue = spotRate * (1 + r_dom * T) / (1 + r_for * T);

const poRate = spotRate * 0.992;
const spotINR = amount * spotRate;
const fwd30INR = amount * forward30d;
const fwd90INR = amount * forward90d;
const fwdDueINR = amount * forwardDue;
const poINR = amount * poRate;

const hedgeCost30 = fwd30INR - spotINR;
const hedgeCost90 = fwd90INR - spotINR;
const hedgeCostDue = fwdDueINR - spotINR;
const exposure = spotINR - poINR;
const exposurePct = ((spotRate - poRate) / poRate * 100);

const intDiff = Math.abs(r_dom - r_for);
const vol30 = intDiff * 12 + 0.5;

let volClass = 'LOW';
if (vol30 > 2.5) volClass = 'EXTREME';
else if (vol30 > 1.5) volClass = 'HIGH';
else if (vol30 > 0.8) volClass = 'MODERATE';

let hedgeRec = false, hedgeType = 'NONE', hedgeReason = '';
if (spotINR > 500000 && vol30 > 1.5) {
  hedgeRec = true; hedgeType = 'FORWARD_AT_DUE';
  hedgeReason = 'High-value + volatile (' + vol30.toFixed(1) + '% est. vol)';
} else if (vol30 > 2.5) {
  hedgeRec = true; hedgeType = 'FORWARD_30D';
  hedgeReason = 'Extreme volatility (' + vol30.toFixed(1) + '%)';
} else if (Math.abs(exposurePct) > 3) {
  hedgeRec = true; hedgeType = 'FORWARD_90D';
  hedgeReason = 'Rate moved ' + exposurePct.toFixed(1) + '% since PO';
}

let timing = 'PAY_AT_SPOT', timingR = 'Stable, pay at spot';
if (hedgeCostDue < 0) {
  timing = 'PAY_NOW_FAVORABLE';
  timingR = 'Forward < spot — domestic strengthening, pay now';
} else if (hedgeCostDue > spotINR * 0.02) {
  timing = 'HEDGE_FORWARD';
  timingR = 'Forward premium ' + ((hedgeCostDue/spotINR)*100).toFixed(2) + '%';
}

let vendorAdv = 'CONTINUE', vendorAdvR = 'FX risk acceptable';
if (vol30 > 2 && spotINR > 300000) {
  vendorAdv = 'RENEGOTIATE_IN_INR'; vendorAdvR = 'High vol + value — renegotiate';
} else if (exposurePct > 5) {
  vendorAdv = 'CONSIDER_ALTERNATIVE'; vendorAdvR = 'Exposure >5% since PO';
}

const riskScore = 0.30*Math.min(vol30/3,1) + 0.25*Math.min(Math.abs(exposurePct)/5,1) + 0.25*(hedgeCostDue>0 ? Math.min(hedgeCostDue/(spotINR*0.03),1) : 0) + 0.20*(spotINR>500000 ? 0.8 : spotINR>200000 ? 0.4 : 0.1);
let riskLevel = 'LOW';
if (riskScore > 0.6) riskLevel = 'HIGH';
else if (riskScore > 0.3) riskLevel = 'MEDIUM';

let swarmVote = 'GO', swarmConf = 0.80;
if (riskLevel === 'HIGH') { swarmVote = 'REVIEW'; swarmConf = 0.75; }
if (volClass === 'EXTREME' && spotINR > 500000) { swarmVote = 'BLOCK'; swarmConf = 0.85; }

return [{
  json: {
    ...prev,
    currency_risk: {
      analysis: 'FOREIGN', rate_source: rateSource, currency: currency,
      amount_foreign: amount,
      spot_rate: parseFloat(spotRate.toFixed(4)),
      spot_inr: parseFloat(spotINR.toFixed(2)),
      forward_30d_rate: parseFloat(forward30d.toFixed(4)),
      forward_30d_inr: parseFloat(fwd30INR.toFixed(2)),
      forward_90d_rate: parseFloat(forward90d.toFixed(4)),
      forward_90d_inr: parseFloat(fwd90INR.toFixed(2)),
      forward_due_rate: parseFloat(forwardDue.toFixed(4)),
      forward_due_inr: parseFloat(fwdDueINR.toFixed(2)),
      cip_formula: 'F = S x (1 + r_INR x T) / (1 + r_' + currency + ' x T)',
      cip_inputs: { S: parseFloat(spotRate.toFixed(4)), r_dom: r_dom, r_for: r_for, T: parseFloat(T.toFixed(4)) },
      po_rate: parseFloat(poRate.toFixed(4)),
      po_inr: parseFloat(poINR.toFixed(2)),
      exposure_since_po: parseFloat(exposure.toFixed(2)),
      exposure_pct: parseFloat(exposurePct.toFixed(2)),
      hedge_cost_30d: parseFloat(hedgeCost30.toFixed(2)),
      hedge_cost_90d: parseFloat(hedgeCost90.toFixed(2)),
      hedge_cost_due: parseFloat(hedgeCostDue.toFixed(2)),
      volatility_est: parseFloat(vol30.toFixed(2)),
      volatility_class: volClass,
      interest_rate_diff: parseFloat(intDiff.toFixed(4)),
      risk_level: riskLevel, risk_score: parseFloat(riskScore.toFixed(3)),
      hedging: {
        recommended: hedgeRec, type: hedgeType, reason: hedgeReason,
        cost_inr: hedgeRec ? parseFloat(hedgeCostDue.toFixed(2)) : 0,
        note: 'Forward via Covered Interest Parity (CIP). Bank-backed OTC forwards for counterparty risk.'
      },
      payment_timing: { recommendation: timing, reason: timingR },
      vendor_advice: { action: vendorAdv, reason: vendorAdvR },
      proceed: riskLevel !== 'HIGH',
      swarm_vote: swarmVote, swarm_confidence: swarmConf
    }
  }
}];

// Currency Risk Post-Process
const input = $input.first().json;
const rawResponse = typeof input.text === 'string' ? input.text : (input.response || input.output || JSON.stringify(input));
const prev = $('Currency Risk Analysis1').first().json;

let currencyResult;
try {
  const cleaned = rawResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  currencyResult = JSON.parse(cleaned);
} catch(e) {
  currencyResult = {
    recommendation: prev.currency_risk.recommendation,
    reasoning: 'LLM parse failed, using algorithmic recommendation',
    projected_saving_if_delayed: 0,
    alert_cfo: false,
    confidence: 0.5
  };
}

return [{
  json: {
    ...prev,
    currency_risk_llm: currencyResult,
    agent_assessments: {
      ...(prev.agent_assessments || {}),
      currency_risk_agent: {
        agent: 'CurrencyRiskAgent',
        recommendation: currencyResult.recommendation,
        exposure: prev.currency_risk.exposure_inr,
        alert_cfo: currencyResult.alert_cfo
      }
    }
  }
}];

