parameters.jsCode:
// Remediation Intelligence Post-Process
const input = $input.first().json;
const rawResponse = typeof input.text === 'string' ? input.text : (input.response || input.output || JSON.stringify(input));
const prev = $('Parse Error1').first().json;

let remResult;
try {
  const cleaned = rawResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  remResult = JSON.parse(cleaned);
} catch(e) {
  remResult = {
    error_explanation: 'Unable to analyze error via LLM',
    deterministic_fix_correct: prev.can_auto_fix,
    additional_fixes: [],
    recurrence_prediction: 'first_time',
    severity: 'MEDIUM',
    reasoning: 'LLM parse failed'
  };
}

return [{
  json: {
    ...prev,
    remediation_intelligence: remResult,
    remediation_logs: [
      ...(prev.remediation_logs || []),
      'LLM_ANALYSIS: ' + remResult.error_explanation,
      'SEVERITY: ' + remResult.severity,
      'RECURRENCE: ' + remResult.recurrence_prediction,
      'DETERMINISTIC_FIX_OK: ' + remResult.deterministic_fix_correct
    ]
  }
}];

// Prepare Analytics Data (V5 — CFO with Swarm Intelligence Metrics)
const invoices = $('Read All Invoices1').all().map(item => item.json);
const swarmFeedback = $('Read Swarm Feedback for CFO').all().map(item => item.json);
const paymentLedger = $('Read Payment Ledger for CFO').all().map(item => item.json);
const webhookInput = $('Webhook - analytics1').first().json;
const body = webhookInput.body || webhookInput;
const userQuery = body.query || null;
const sessionId = body.session_id || body.user_id || body.conversation_id || 'analytics-global';

// === INVOICE ANALYTICS ===
const totalInvoices = invoices.length;
const totalAmount = invoices.reduce((sum, inv) => sum + (parseFloat(inv.amount) || 0), 0);

const vendorSpend = {};
invoices.forEach(inv => {
  const v = inv.vendor_name || 'Unknown';
  vendorSpend[v] = (vendorSpend[v] || 0) + (parseFloat(inv.amount) || 0);
});

const statusCounts = {};
invoices.forEach(inv => {
  const s = inv.status || 'UNKNOWN';
  statusCounts[s] = (statusCounts[s] || 0) + 1;
});

const riskCounts = {};
invoices.forEach(inv => {
  const r = inv.risk_level || 'UNKNOWN';
  riskCounts[r] = (riskCounts[r] || 0) + 1;
});

const confidences = invoices.map(inv => parseFloat(inv.confidence) || 0);
const avgConfidence = confidences.length > 0 ? (confidences.reduce((a,b) => a+b, 0) / confidences.length) : 0;

const autoReadyStatuses = new Set(['PARSED_READY', 'AUTO_APPROVED', 'APPROVED']);
const autoReadyCount = invoices.filter(inv => autoReadyStatuses.has(String(inv.status || '').toUpperCase())).length;
const needsHumanCount = invoices.filter(inv => String(inv.status || '').toUpperCase() === 'NEEDS_HUMAN').length;
const lowConfidenceCount = invoices.filter(inv => (parseFloat(inv.confidence) || 0) < 0.6).length;
const highRiskCount = invoices.filter(inv => String(inv.risk_level || '').toUpperCase() === 'HIGH').length;

const topVendors = Object.entries(vendorSpend)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([vendor, spend]) => ({ vendor, spend }));

// === PAYMENT ANALYTICS ===
const totalPayments = paymentLedger.length;
const successPayments = paymentLedger.filter(p => String(p.status || '').includes('SUCCESS')).length;
const failedPayments = paymentLedger.filter(p => String(p.status || '').includes('FAIL')).length;
const paymentSuccessRate = totalPayments > 0 ? parseFloat((successPayments / totalPayments).toFixed(3)) : 0;
const totalPaid = paymentLedger.filter(p => String(p.status || '').includes('SUCCESS')).reduce((s, p) => s + (parseFloat(p.amount) || 0), 0);
const verifiedPayments = paymentLedger.filter(p => String(p.verified) === 'true' || p.verified === true).length;
const verificationRate = totalPayments > 0 ? parseFloat((verifiedPayments / totalPayments).toFixed(3)) : 0;

// === SWARM INTELLIGENCE ANALYTICS ===
const totalSwarmDecisions = swarmFeedback.length;
const resolvedFeedback = swarmFeedback.filter(r => r.payment_status && r.payment_status !== 'PENDING' && r.payment_status !== '');
const swarmSuccesses = resolvedFeedback.filter(r => r.payment_status === 'PAYMENT_SUCCESS').length;
const swarmBlocked = resolvedFeedback.filter(r => r.payment_status === 'SWARM_BLOCKED').length;
const swarmFailed = resolvedFeedback.filter(r => r.payment_status === 'PAYMENT_FAILED' || r.payment_status === 'REMEDIATION_FAILED').length;
const swarmSuccessRate = resolvedFeedback.length > 0 ? parseFloat((swarmSuccesses / resolvedFeedback.length).toFixed(3)) : 0;
const swarmBlockRate = resolvedFeedback.length > 0 ? parseFloat((swarmBlocked / resolvedFeedback.length).toFixed(3)) : 0;

// Latest adapted weights (from most recent feedback row)
let latestWeights = { anomaly: 0.40, currency: 0.25, vendor: 0.35 };
let weightsAdapted = false;
if (swarmFeedback.length > 0) {
  const latest = swarmFeedback[swarmFeedback.length - 1];
  try {
    latestWeights = typeof latest.weights_used === 'string' ? JSON.parse(latest.weights_used) : latest.weights_used;
    weightsAdapted = latest.feedback_adapted === 'true' || latest.feedback_adapted === true;
  } catch(e) {}
}

// Per-agent accuracy from resolved feedback
let agentAccuracySummary = { anomaly: 'N/A', currency: 'N/A', vendor: 'N/A' };
const accuracyRows = resolvedFeedback.filter(r => r.agent_accuracy && r.agent_accuracy !== '');
if (accuracyRows.length > 0) {
  let correct = { anomaly: 0, currency: 0, vendor: 0 };
  let total = { anomaly: 0, currency: 0, vendor: 0 };
  for (const row of accuracyRows) {
    let acc;
    try { acc = typeof row.agent_accuracy === 'string' ? JSON.parse(row.agent_accuracy) : row.agent_accuracy; } catch(e) { continue; }
    for (const agent of ['anomaly', 'currency', 'vendor']) {
      if (acc[agent] !== undefined && acc[agent] !== null) {
        total[agent]++;
        if (acc[agent]) correct[agent]++;
      }
    }
  }
  for (const agent of ['anomaly', 'currency', 'vendor']) {
    agentAccuracySummary[agent] = total[agent] > 0 ? parseFloat((correct[agent] / total[agent] * 100).toFixed(1)) + '%' : 'N/A';
  }
}

const summary = {
  session_id: sessionId,
  // Invoice metrics
  total_invoices: totalInvoices,
  total_amount: totalAmount,
  avg_confidence: parseFloat(avgConfidence.toFixed(2)),
  vendor_spend: vendorSpend,
  top_vendors: topVendors,
  status_breakdown: statusCounts,
  risk_breakdown: riskCounts,
  auto_ready_count: autoReadyCount,
  needs_human_count: needsHumanCount,
  low_confidence_count: lowConfidenceCount,
  high_risk_count: highRiskCount,
  automation_readiness_rate: totalInvoices ? parseFloat((autoReadyCount / totalInvoices).toFixed(2)) : 0,
  human_review_rate: totalInvoices ? parseFloat((needsHumanCount / totalInvoices).toFixed(2)) : 0,
  // Payment metrics
  total_payments: totalPayments,
  payment_success_count: successPayments,
  payment_failed_count: failedPayments,
  payment_success_rate: paymentSuccessRate,
  total_paid_amount: totalPaid,
  verification_rate: verificationRate,
  // Swarm intelligence metrics
  total_swarm_decisions: totalSwarmDecisions,
  swarm_resolved_count: resolvedFeedback.length,
  swarm_success_rate: swarmSuccessRate,
  swarm_block_rate: swarmBlockRate,
  swarm_blocked_count: swarmBlocked,
  swarm_failed_count: swarmFailed,
  swarm_weights_adapted: weightsAdapted,
  swarm_current_weights: latestWeights,
  agent_accuracy: agentAccuracySummary,
  system_learning_active: resolvedFeedback.length >= 3 && weightsAdapted
};

const dataContext = JSON.stringify(summary);
const promptText = userQuery
  ? 'SESSION: ' + sessionId + '\nINVOICE & PAYMENT DATA:\n' + dataContext + '\n\nCFO QUESTION: ' + userQuery + '\n\nAnswer using the data. Include swarm intelligence health, payment success rates, agent accuracy, and learning status. Respond in JSON: {query_answer, executive_summary, recommendations, scenario_analysis, swarm_health, confidence}'
  : 'SESSION: ' + sessionId + '\nINVOICE & PAYMENT DATA:\n' + dataContext + '\n\nGenerate CFO briefing covering: executive summary, payment pipeline health, swarm intelligence learning status (weight adaptation, agent accuracy), top vendors, automation readiness, risk, cash flow, anomalies, and recommendations. Include swarm_health section with learning metrics. Respond in JSON.';

return [{ json: { session_id: sessionId, analytics_data: summary, user_query: userQuery, text: promptText } }];

// === Swarm Data Aggregator ===
// Consolidates real vendor history + live FX + policy data into single item
// Feeds all 3 swarm agents with the data they need

const policyData = $('Validate Supervisor & Policy Rules1').first().json;
const vendorHistoryRows = $('Read Vendor History1').all();
const fxData = $('Fetch Live FX Rates1').first().json;

// Build vendor statistics from REAL invoice history
const vendorStats = {};
const allAmounts = [];

for (const row of vendorHistoryRows) {
  const vendor = (row.json.vendor_name || '').trim();
  const amount = parseFloat(row.json.amount);
  if (!vendor || isNaN(amount) || amount <= 0) continue;
  allAmounts.push(amount);
  const key = vendor.toLowerCase();
  if (!vendorStats[key]) {
    vendorStats[key] = { amounts: [], count: 0, name: vendor };
  }
  vendorStats[key].amounts.push(amount);
  vendorStats[key].count++;
}

// Compute per-vendor stats
for (const key of Object.keys(vendorStats)) {
  const a = vendorStats[key].amounts;
  const mean = a.reduce((s,v) => s+v, 0) / a.length;
  const stddev = a.length > 1
    ? Math.sqrt(a.map(x => Math.pow(x - mean, 2)).reduce((s,v) => s+v, 0) / a.length)
    : mean * 0.2;
  vendorStats[key].mean = mean;
  vendorStats[key].stddev = stddev;
  vendorStats[key].min = Math.min(...a);
  vendorStats[key].max = Math.max(...a);
}

// Global stats
const gMean = allAmounts.length > 0 ? allAmounts.reduce((a,b) => a+b, 0) / allAmounts.length : 50000;
const gStd = allAmounts.length > 1
  ? Math.sqrt(allAmounts.map(x => Math.pow(x - gMean, 2)).reduce((a,b) => a+b, 0) / allAmounts.length)
  : 20000;
const vCount = Object.keys(vendorStats).length;

return [{
  json: {
    ...policyData,
    vendor_stats: vendorStats,
    global_stats: {
      total_invoices: allAmounts.length,
      mean: gMean,
      stddev: gStd,
      vendor_count: vCount,
      avg_vendor_count: vCount > 0 ? allAmounts.length / vCount : 3
    },
    live_fx: fxData || null
  }
}];

// === SWARM AGENT 3: Vendor Trust Scorer ===
// Computes vendor reliability from real invoice history

const prev = $('Anomaly Post-Process1').first().json;
const vendorName = (prev.invoice_data.vendor_name || '').toLowerCase();
const amount = prev.execution_payload.amount;
const vendorStats = prev.vendor_stats || {};

const vendorKey = Object.keys(vendorStats).find(k =>
  vendorName.includes(k) || k.includes(vendorName)
) || null;

let trustScore = 0.3;
let trustLevel = 'UNKNOWN';
const logs = [];

if (vendorKey) {
  const s = vendorStats[vendorKey];
  const tenureScore = Math.min(s.count / 10, 1);
  const cv = s.mean > 0 ? (s.stddev / s.mean) : 1;
  const consistencyScore = Math.max(0, 1 - cv);
  const amountRatio = s.mean > 0 ? amount / s.mean : 2;
  const amountScore = amountRatio <= 1.5 ? 1.0 : amountRatio <= 2.5 ? 0.6 : 0.2;

  trustScore = 0.35 * tenureScore + 0.30 * consistencyScore + 0.35 * amountScore;
  trustLevel = trustScore >= 0.7 ? 'HIGH' : trustScore >= 0.4 ? 'MEDIUM' : 'LOW';

  logs.push('VENDOR_MATCHED: ' + s.name + ' (' + s.count + ' prior invoices)');
  logs.push('TENURE: ' + tenureScore.toFixed(2) + ' | CONSISTENCY: ' + consistencyScore.toFixed(2) + ' (CV=' + cv.toFixed(2) + ')');
  logs.push('AMOUNT_RATIO: ' + amountRatio.toFixed(2) + ' → score=' + amountScore.toFixed(2));
} else {
  logs.push('VENDOR_NOT_FOUND: "' + prev.invoice_data.vendor_name + '" — no history');
  logs.push('DEFAULT_TRUST: 0.30 (unknown vendor penalty)');
}

let swarmVote = 'GO', swarmConf = 0.70;
if (trustScore < 0.25) { swarmVote = 'BLOCK'; swarmConf = 0.80; }
else if (trustScore < 0.45) { swarmVote = 'REVIEW'; swarmConf = 0.70; }

logs.push('TRUST_SCORE: ' + trustScore.toFixed(3) + ' | LEVEL: ' + trustLevel);
logs.push('SWARM_VOTE: ' + swarmVote + ' (conf=' + swarmConf + ')');

return [{
  json: {
    ...prev,
    vendor_trust: {
      trust_score: parseFloat(trustScore.toFixed(3)),
      trust_level: trustLevel,
      vendor_matched: vendorKey || null,
      trust_logs: logs,
      swarm_vote: swarmVote,
      swarm_confidence: swarmConf
    }
  }
}];

parameters.text:
=You are a Vendor Trust Assessment Agent in a swarm intelligence system for enterprise accounts payable.

VENDOR: {{ $json.invoice_data.vendor_name }}
INVOICE: {{ $json.execution_payload.currency }} {{ $json.execution_payload.amount }}

ALGORITHMIC TRUST METRICS:
- Trust Score: {{ $json.vendor_trust.trust_score }} / 1.0
- Trust Level: {{ $json.vendor_trust.trust_level }}
- Vendor history: {{ $json.vendor_trust.vendor_matched ? 'KNOWN — matched in history' : 'UNKNOWN — no prior invoices' }}

ANOMALY CONTEXT:
- Z-Score: {{ $json.anomaly.z_score }} ({{ Math.abs($json.anomaly.z_score) > 2 ? 'UNUSUAL' : 'NORMAL' }})
- Anomaly composite: {{ $json.anomaly.composite_score }}
- Data source: {{ $json.anomaly.data_source }}

POLICY CONTEXT:
- Policy decision: {{ $json.policy.decision }}
- Risk score: {{ $json.policy.risk_score }}
- Reason codes: {{ $json.policy.reason_codes.join(', ') }}

Your task — independent assessment for swarm consensus:
1. Is this vendor trustworthy for this specific transaction?
2. Does the invoice amount make sense given vendor history?
3. Any red flags (new vendor + large amount, frequency spike, currency mismatch)?

Return ONLY JSON:
{
  "trust_assessment": "TRUSTED" | "CAUTIOUS" | "UNTRUSTED",
  "reasoning": "2-3 sentences of business context assessment",
  "recommended_action": "PROCEED" | "FLAG_FOR_REVIEW" | "BLOCK",
  "red_flags": ["list any concerns"],
