parameters.jsCode:
// Vendor Trust Agent Post-Process
const input = $input.first().json;
const raw = typeof input.text === 'string' ? input.text : (input.response || input.output || JSON.stringify(input));
const prev = $('Vendor Trust Scorer1').first().json;

let result;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  result = JSON.parse(cleaned);
} catch(e) {
  result = {
    trust_assessment: prev.vendor_trust.trust_level === 'HIGH' ? 'TRUSTED' : 'CAUTIOUS',
    reasoning: 'LLM parse failed, using algorithmic assessment',
    recommended_action: prev.vendor_trust.swarm_vote === 'GO' ? 'PROCEED' : 'FLAG_FOR_REVIEW',
    confidence: 0.5
  };
}

let vote = prev.vendor_trust.swarm_vote;
let conf = prev.vendor_trust.swarm_confidence;
if (result.recommended_action === 'BLOCK') {
  vote = 'BLOCK'; conf = Math.max(conf, result.confidence);
} else if (result.recommended_action === 'FLAG_FOR_REVIEW' && vote === 'GO') {
  vote = 'REVIEW'; conf = result.confidence;
}

return [{
  json: {
    ...prev,
    vendor_trust: {
      ...prev.vendor_trust,
      llm_assessment: result,
      swarm_vote: vote,
      swarm_confidence: conf
    }
  }
}];

// === SWARM CONSENSUS ENGINE V3 — REAL CLOSED FEEDBACK LOOP ===
// Fixes: reads payment_status (not status), per-agent tracking, temporal weighting,
//        proper normalization, reward/penalty per agent, weight persistence
// Get ORIGINAL enriched payload (source of truth)
const original = $('Vendor Trust Post-Process1').first().json;

// Get feedback rows separately
const feedbackItems = $('Read Swarm Feedback').all().map(r => r.json);

// Use original as base
const prev = original;
const traceId = original.trace_id;

// === READ HISTORICAL FEEDBACK WITH OUTCOMES ===
const allFeedback = $('Read Swarm Feedback').all().map(r => r.json);
// Only consider rows that have a resolved payment_status (not PENDING)
const resolvedFeedback = allFeedback.filter(r =>
  r.payment_status && r.payment_status !== 'PENDING' && r.payment_status !== ''
);

const BASE_W = { anomaly: 0.40, currency: 0.25, vendor: 0.35 };
const LEARNING_RATE = 0.05;
const MIN_HISTORY = 3;
const TEMPORAL_DECAY = 0.95; // recent feedback weighted more

let W = { ...BASE_W };
let feedbackAnalysis = {
  history_size: allFeedback.length,
  resolved_size: resolvedFeedback.length,
  adapted: false,
  adjustments: [],
  agent_scores: { anomaly: 0.5, currency: 0.5, vendor: 0.5 }
};

if (resolvedFeedback.length >= MIN_HISTORY) {
  // === TEMPORAL-WEIGHTED SUCCESS/FAILURE ANALYSIS ===
  const successPayments = resolvedFeedback.filter(r => r.payment_status === 'PAYMENT_SUCCESS');
  const failedPayments = resolvedFeedback.filter(r =>
    r.payment_status === 'PAYMENT_FAILED' || r.payment_status === 'REMEDIATION_FAILED'
  );
  const blockedPayments = resolvedFeedback.filter(r => r.payment_status === 'SWARM_BLOCKED');

  const totalResolved = resolvedFeedback.length;
  const successRate = totalResolved > 0 ? successPayments.length / totalResolved : 0.5;
  const failRate = totalResolved > 0 ? failedPayments.length / totalResolved : 0;
  const blockRate = totalResolved > 0 ? blockedPayments.length / totalResolved : 0;

  feedbackAnalysis.success_rate = parseFloat(successRate.toFixed(3));
  feedbackAnalysis.total_success = successPayments.length;
  feedbackAnalysis.total_failed = failedPayments.length;
  feedbackAnalysis.total_blocked = blockedPayments.length;

  // === PER-AGENT ACCURACY (from agent_accuracy field) ===
  let agentCorrect = { anomaly: 0, currency: 0, vendor: 0 };
  let agentTotal = { anomaly: 0, currency: 0, vendor: 0 };

  for (let i = 0; i < resolvedFeedback.length; i++) {
    const row = resolvedFeedback[i];
    let accuracy;
    try { accuracy = typeof row.agent_accuracy === 'string' ? JSON.parse(row.agent_accuracy) : row.agent_accuracy; } catch(e) { continue; }
    if (!accuracy) continue;
    const weight = Math.pow(TEMPORAL_DECAY, resolvedFeedback.length - 1 - i); // newer = higher weight
    for (const agent of ['anomaly', 'currency', 'vendor']) {
      if (accuracy[agent] !== undefined) {
        agentTotal[agent] += weight;
        if (accuracy[agent]) agentCorrect[agent] += weight;
      }
    }
  }

  // Compute per-agent accuracy scores
  for (const agent of ['anomaly', 'currency', 'vendor']) {
    feedbackAnalysis.agent_scores[agent] = agentTotal[agent] > 0
      ? parseFloat((agentCorrect[agent] / agentTotal[agent]).toFixed(3))
      : 0.5;
  }

  // === WEIGHT UPDATE: Based on agent accuracy + overall performance ===
  // REWARD: Agents with high accuracy get weight boost
  // PENALTY: Agents with low accuracy get weight reduction
  if (failedPayments.length > 0 && successRate < 0.8) {
    const failRatio = failedPayments.length / totalResolved;

    // Identify which agents contributed to failures
    for (const agent of ['anomaly', 'currency', 'vendor']) {
      const agentAcc = feedbackAnalysis.agent_scores[agent];
      if (agentAcc < 0.5) {
        // Low-accuracy agent: BOOST weight (it needs more say to catch issues)
        W[agent] = Math.min(0.60, W[agent] + LEARNING_RATE * (1 - agentAcc));
        feedbackAnalysis.adjustments.push('BOOST_' + agent.toUpperCase() + ': accuracy=' + (agentAcc * 100).toFixed(1) + '%');
      } else if (agentAcc > 0.8) {
        // High-accuracy agent: REWARD with slight boost
        W[agent] = Math.min(0.55, W[agent] + LEARNING_RATE * 0.3);
        feedbackAnalysis.adjustments.push('REWARD_' + agent.toUpperCase() + ': accuracy=' + (agentAcc * 100).toFixed(1) + '%');
      }
    }
    feedbackAnalysis.adapted = true;
  }

  // RELAX: If system is performing very well, relax anomaly strictness
  if (successRate > 0.95 && resolvedFeedback.length >= 10) {
    const relaxAmount = LEARNING_RATE * 0.5;
    W.anomaly = Math.max(0.25, W.anomaly - relaxAmount);
    W.vendor = Math.min(0.50, W.vendor + relaxAmount * 0.6);
    W.currency = Math.min(0.40, W.currency + relaxAmount * 0.4);
    feedbackAnalysis.adjustments.push('RELAX: high success rate ' + (successRate * 100).toFixed(1) + '%');
    feedbackAnalysis.adapted = true;
  }

  // HIGH BLOCK RATE: If blocking too much, reduce sensitivity
  if (blockRate > 0.5 && totalResolved >= 5) {
    W.anomaly = Math.max(0.25, W.anomaly - LEARNING_RATE);
    feedbackAnalysis.adjustments.push('REDUCE_BLOCKING: block rate ' + (blockRate * 100).toFixed(1) + '%');
    feedbackAnalysis.adapted = true;
  }

  // === NORMALIZE WEIGHTS TO SUM TO 1 ===
  const total = W.anomaly + W.currency + W.vendor;
  W.anomaly = parseFloat((W.anomaly / total).toFixed(3));
  W.currency = parseFloat((W.currency / total).toFixed(3));
  W.vendor = parseFloat((1 - W.anomaly - W.currency).toFixed(3));
}

if (!feedbackAnalysis.adapted) {
  feedbackAnalysis.adjustments.push('USING_BASE_WEIGHTS: ' +
    (resolvedFeedback.length < MIN_HISTORY
      ? 'insufficient resolved history (' + resolvedFeedback.length + '/' + MIN_HISTORY + ')'
      : 'system performing within thresholds'));
}

// === AGENT VOTES ===
const aVote = prev.anomaly?.swarm_vote || 'GO';
const aConf = prev.anomaly?.swarm_confidence || 0.5;
const aScore = prev.anomaly?.composite_score || 0;
const cVote = prev.currency_risk?.swarm_vote || 'GO';
const cConf = prev.currency_risk?.swarm_confidence || 0.5;
const cRisk = prev.currency_risk?.risk_score || 0;
const vVote = prev.vendor_trust?.swarm_vote || 'GO';
const vConf = prev.vendor_trust?.swarm_confidence || 0.5;
const vTrust = prev.vendor_trust?.trust_score || 0.5;

// === WEIGHTED CONSENSUS ===
const toNum = (v) => v === 'BLOCK' ? 1.0 : v === 'REVIEW' ? 0.5 : 0.0;
const wScore = W.anomaly * toNum(aVote) * aConf +
               W.currency * toNum(cVote) * cConf +
               W.vendor * toNum(vVote) * vConf;

let decision = 'GO';
if (wScore >= 0.45) decision = 'BLOCK';
else if (wScore >= 0.20) decision = 'REVIEW';

// VETO: Any single agent with high-confidence BLOCK
if ((aVote === 'BLOCK' && aConf > 0.85) || (cVote === 'BLOCK' && cConf > 0.85) || (vVote === 'BLOCK' && vConf > 0.85)) decision = 'BLOCK';
// MAJORITY: 2+ agents vote BLOCK
const blockCount = [aVote, cVote, vVote].filter(v => v === 'BLOCK').length;
if (blockCount >= 2) decision = 'BLOCK';

const proceedToPayment = (decision === 'GO' || decision === 'REVIEW');

const logs = [
  'FEEDBACK_LOOP: total=' + allFeedback.length + ' resolved=' + resolvedFeedback.length + ' adapted=' + feedbackAnalysis.adapted,
  'AGENT_ACCURACY: anomaly=' + feedbackAnalysis.agent_scores.anomaly + ' currency=' + feedbackAnalysis.agent_scores.currency + ' vendor=' + feedbackAnalysis.agent_scores.vendor,
  'WEIGHTS: anomaly=' + W.anomaly + ' currency=' + W.currency + ' vendor=' + W.vendor + (feedbackAnalysis.adapted ? ' (ADAPTED)' : ' (BASE)'),
  'AGENT_1 (Anomaly): ' + aVote + ' conf=' + aConf + ' composite=' + aScore,
  'AGENT_2 (CurrencyRisk): ' + cVote + ' conf=' + cConf + ' risk=' + cRisk,
  'AGENT_3 (VendorTrust): ' + vVote + ' conf=' + vConf + ' trust=' + vTrust,
  'WEIGHTED_SCORE: ' + wScore.toFixed(3),
  'BLOCK_VOTES: ' + blockCount + '/3',
  'CONSENSUS: ' + decision + ' -> ' + (proceedToPayment ? 'PROCEED' : 'HALT')
];

return [{
  json: {
    ...prev,
    swarm_consensus: {
      decision, proceed_to_payment: proceedToPayment,
      weighted_score: parseFloat(wScore.toFixed(3)),
      weights_used: W, base_weights: BASE_W, feedback_analysis: feedbackAnalysis,
      votes: {
        anomaly: { vote: aVote, confidence: aConf, weight: W.anomaly },
        currency: { vote: cVote, confidence: cConf, weight: W.currency },
        vendor: { vote: vVote, confidence: vConf, weight: W.vendor }
      },
      block_votes: blockCount, consensus_logs: logs
    }
  }
}];

