// === Compute Agent Accuracy — Ground Truth Evaluation ===
// Runs AFTER payment outcome is known. Evaluates each agent's vote correctness.
const prev = $input.first().json;
const paymentStatus = prev.payment_status; // from Validate & Verify Payment
const traceId = prev.trace_id;

// Retrieve the swarm consensus data
const swarmData = $('Swarm Consensus Engine1').first().json;
const votes = swarmData.swarm_consensus?.votes || {};

// GROUND TRUTH: Was the payment decision correct?
// If payment succeeded → agents who voted GO were correct, BLOCK was wrong
// If payment failed → agents who voted BLOCK were correct, GO was wrong
const paymentSucceeded = (paymentStatus === 'PAYMENT_SUCCESS');
const wasBlocked = (paymentStatus === 'SWARM_BLOCKED');

let agentAccuracy = {};
for (const [agent, data] of Object.entries(votes)) {
  const agentVote = data.vote || 'GO';
  if (paymentSucceeded) {
    // Payment worked → GO/REVIEW were correct, BLOCK was wrong
    agentAccuracy[agent] = (agentVote === 'GO' || agentVote === 'REVIEW');
  } else if (wasBlocked) {
    // Was blocked — we don't know ground truth for blocked items
    // Score neutral (agents who blocked get slight credit for caution)
    agentAccuracy[agent] = (agentVote === 'BLOCK') ? true : null; // null = unknown
  } else {
    // Payment failed → BLOCK/REVIEW were correct, GO was wrong
    agentAccuracy[agent] = (agentVote === 'BLOCK' || agentVote === 'REVIEW');
  }
}

return [{
  json: {
    trace_id: traceId,
    payment_status: paymentStatus,
    agent_accuracy: JSON.stringify(agentAccuracy),
    outcome_timestamp: new Date().toISOString()
