const retryResponse = $input.first().json;
const policyData = $('Validate Supervisor & Policy Rules1').first().json;
const expectedPayload = $('Parse Error1').first().json.patched_payload;
const traceId = policyData.trace_id;
const idempotencyKey = policyData.idempotency_key;

const actionLogs = [];
const verificationLogs = [];

const apiStatus = retryResponse.status || retryResponse.body?.status || 'UNKNOWN';
const httpCode = retryResponse.http_code || retryResponse.statusCode || retryResponse.body?.http_code || 0;
const txnId = retryResponse.transaction_id || retryResponse.body?.transaction_id || null;

let paymentStatus;
let paymentSuccess = false;

if (apiStatus === 'SUCCESS' && httpCode === 200) {
  paymentStatus = 'PAYMENT_SUCCESS';
  paymentSuccess = true;
  actionLogs.push('OK: Remediation retry succeeded');
  actionLogs.push('TXN_ID: ' + txnId);
} else {
  paymentStatus = 'REMEDIATION_FAILED';
  actionLogs.push('FAIL: Remediation retry failed');
}

let verified = false;
let verificationStatus = 'UNVERIFIED';

if (paymentSuccess) {
  const returnedAmount = retryResponse.amount || retryResponse.body?.amount;
  if (returnedAmount === expectedPayload.amount) {
    verificationLogs.push('VERIFY OK: amount matches');
  } else {
    verificationLogs.push('VERIFY FAIL: amount mismatch');
    verificationStatus = 'AMOUNT_MISMATCH';
  }

  const returnedBeneficiary = retryResponse.beneficiary_name || retryResponse.body?.beneficiary_name || '';
  if (returnedBeneficiary.toLowerCase() === expectedPayload.beneficiary_name.toLowerCase()) {
    verificationLogs.push('VERIFY OK: beneficiary matches');
  } else {
    verificationLogs.push('VERIFY FAIL: beneficiary mismatch');
    verificationStatus = 'BENEFICIARY_MISMATCH';
