  if (returnedCurrency === expectedPayload.currency) {
    verificationLogs.push('VERIFY OK: currency matches');
  } else {
    verificationLogs.push('VERIFY FAIL: currency mismatch');
    verificationStatus = 'CURRENCY_MISMATCH';
